float sdLine(vec2 p, vec2 a, vec2 b) {
    vec2 pa = p - a, ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    return length(pa - ba * h);
}

float S(float v) {
    vec2 r = vec2(iResolution.x, iResolution.y);
    float aa_width = 1.5/r.y;
    return smoothstep(aa_width, 0.0, v);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec3 col = vec3(0.444);

    float lineWidth = 0.001; 
    float pointWidth = 0.01; 
    float angleWidth = 0.002;

    float d = sdOuter(uv);
    col = mix(col, vec3(1.0), S(abs(d) - lineWidth));
    col = mix(col, vec3(0.125), 1.0 - S(d - lineWidth*2.0));

    for(int i = 0; i < NUM_PRIMITIVES; i++) {
        vec2 pos = texelFetch(iChannel0, ivec2(0, i), 0).xy;
        vec2 b = texelFetch(iChannel0, ivec2(1, i), 0).xy;
        vec4 r = texelFetch(iChannel0, ivec2(2, i), 0);
        float angle = texelFetch(iChannel0, ivec2(6, i), 0).x;

        float d2 = sdRoundedBox(uv, pos, b, r, angle);


        col = mix(col, vec3(0.888), S(abs(d2) - lineWidth));
        col = mix(col, vec3(0.75), 1.0 - step(0.0, d2));

        seed = (iFrame * 32 + i * 1337);
        vec2 randPos = pos + randomInCircle() * max(b.x, b.y);
        vec2 surfPos = randPos + sdRoundedBoxGrad(randPos, pos, b, r, angle) * -sdRoundedBox(randPos, pos, b, r, angle);

        vec2 closestOuter = surfPos - sdOuterGrad(surfPos) * sdOuter(surfPos);
        float distToOuter = sdOuter(surfPos);

        vec2 closestPrim = closestOuter;
        float minDist = distToOuter;

        for(int j = 0; j < NUM_PRIMITIVES; j++) {
            if(j != i) {
                vec2 otherPos = texelFetch(iChannel0, ivec2(0, j), 0).xy;
                vec2 otherB = texelFetch(iChannel0, ivec2(1, j), 0).xy;
                vec4 otherR = texelFetch(iChannel0, ivec2(2, j), 0);
                float otherAngle = texelFetch(iChannel0, ivec2(6, j), 0).x;

                float distToPrim = sdRoundedBox(surfPos, otherPos, otherB, otherR, otherAngle);
                if(-distToPrim > minDist) {
                    vec2 grad = sdRoundedBoxGrad(surfPos, otherPos, otherB, otherR, otherAngle);
                    closestPrim = surfPos - grad * distToPrim;
                    minDist = -distToPrim;
                }
            }
        }

        col = mix(col, (col + 1.0) * 0.5, S(sdLine(uv, surfPos, closestPrim) - lineWidth/2.0));
        col = mix(col, (col + 1.0) * 0.5, S(length(uv - surfPos) - pointWidth));
        col = mix(col, (col + vec3(1.0, 0.5, 0.0)) * 0.5, S(length(uv - closestPrim) - pointWidth));

        vec2 angleVec = rotate2D(vec2(0.03, 0.0), angle);
        col = mix(col, vec3(1.0), S(sdLine(uv, pos, pos + angleVec) - angleWidth));
    }

    fragColor = vec4(col, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    int index = int(fragCoord.y);

    if(fragCoord.y < float(NUM_PRIMITIVES)) {
        vec2 pos = texelFetch(iChannel0, ivec2(0, index), 0).xy;
        vec2 b = texelFetch(iChannel0, ivec2(1, index), 0).xy;
        vec4 r = texelFetch(iChannel0, ivec2(2, index), 0);
        vec2 vb = texelFetch(iChannel0, ivec2(3, index), 0).xy;
        vec4 vr = texelFetch(iChannel0, ivec2(4, index), 0);
        vec2 vpos = texelFetch(iChannel0, ivec2(5, index), 0).xy;
        float angle = texelFetch(iChannel0, ivec2(6, index), 0).x;
        float vangle = texelFetch(iChannel0, ivec2(7, index), 0).x;
        if(iFrame < 1) { 
            pos = index == 4 ? vec2(0.0) : vec2(index % 2 == 0 ? 0.175 : -0.175, index > 1 ? 0.175 : -0.175);
            b = index == 4 ? vec2(0.09) : vec2(0.04); 
            r = index == 4 ? vec4(0.09) : vec4(0.04);
            vb = vec2(0.0);
            vr = vec4(0.0);
            vpos = vec2(0.0);
            angle = 0.0;
            vangle = 0.0;
        }

        seed = iFrame * 38142719;

        bool collided = false;
        vec2 sumB = vec2(0.0); 
        vec4 sumR = vec4(0.0);
        vec2 sumPos = vec2(0.0);
        float sumAngle = 0.0;
        float count = 0.0;
        float avgPenetration = 0.0;

        for (int i = 0; i < 48; i++) {
            vec2 randPos = pos + randomInCircle() * max(b.x, b.y);
            vec2 surfPos = randPos + sdRoundedBoxGrad(randPos, pos, b, r, angle) *  -sdRoundedBox(randPos, pos, b, r, angle);

            bool innerCollision = false;
            float dist = sdOuter(surfPos) + PROXIMITY;
            for (int otherIndex = 0; otherIndex < NUM_PRIMITIVES; otherIndex++) {
            if(otherIndex != index) {  
                vec2 otherPos = texelFetch(iChannel0, ivec2(0, otherIndex), 0).xy;
                vec2 otherB = texelFetch(iChannel0, ivec2(1, otherIndex), 0).xy;
                vec4 otherR = texelFetch(iChannel0, ivec2(2, otherIndex), 0);
                float otherAngle = texelFetch(iChannel0, ivec2(6, otherIndex), 0).x;
                float candidate = -sdRoundedBox(surfPos, otherPos, otherB, otherR, otherAngle) + PROXIMITY;
                if (candidate > dist) {
                    dist = candidate;
                    innerCollision = true;
                }
               }
            }

            float sd = sign(dist);
            if(dist != 0.0) {
                vec4 dr;
                vec2 db, dpos;
                float dangle;
                float angleUpdate;
                float weight = innerCollision ? 0.25 : 1.0;

                computeGrowthDerivatives(surfPos, pos, b, r, angle, db);
                computeRadiusDerivatives(surfPos, pos, b, r, angle, dr);
                computePositionDerivatives(surfPos, pos, b, r, angle, dpos);
                computeRotationUpdate(surfPos, pos, angle, angleUpdate);

                sumB += db * weight * sd;
                sumR += dr * pow(weight, 0.5) * sd;
                sumAngle += angleUpdate * pow(weight, 2.0) * sd;
                sumPos += dpos * weight * sd;

                avgPenetration += abs(sd);
                count += 1.0;
                collided = true;
            }
        }


        if(collided) {
            avgPenetration /= count;
        }

        float damping = 0.995;
        float momentum = mix(0.95, 0.9, smoothstep(0.0, 20.0, iTime));

        if (!collided) {
            vb = vb * damping;
            vr = vr * damping;
            vpos = vpos * damping;

        } else {
            float countNorm = max(1.0, count);

            float updateScale = smoothstep(-0.015, 0.0, avgPenetration) * 0.1;
            vb = vb * momentum + (sumB / countNorm) * 0.01 * updateScale;
            vr = vr * momentum + -(sumR / countNorm) * 0.01 * updateScale;
            vpos = vpos * momentum + (sumPos / countNorm) * 0.01 * updateScale;
            vangle = vangle * momentum + (sumAngle / countNorm) * 0.1 * updateScale;

            vb *= damping;
            vr *= damping;
            vpos *= damping;
            vangle *= damping;
        }

        b += vb;
        r -= vr;
        pos += vpos;
        angle += vangle;

        b = max(b, vec2(0.02));
        r = min(r, vec4(min(b.x, b.y)));
        pos = clamp(pos, vec2(-0.3), vec2(0.3));
        angle = mod(angle + PI, 2.0 * PI) - PI;

        vb = mix(vb, vec2(0.0), step(b, vec2(0.02)));
        vr = mix(vr, vec4(0.0), step(r, vec4(0.01)));
        vr = mix(vr, vec4(0.0), step(vec4(min(b.x, b.y)), r));
        vpos = mix(vpos, vec2(0.0), step(abs(pos), vec2(0.3)));

        if(fragCoord.x < 1.0) fragColor = vec4(pos, 0.0, 1.0);
        else if(fragCoord.x < 2.0) fragColor = vec4(b, 0.0, 1.0);
        else if(fragCoord.x < 3.0) fragColor = r;
        else if(fragCoord.x < 4.0) fragColor = vec4(vb, 0.0, 1.0);
        else if(fragCoord.x < 5.0) fragColor = vr;
        else if(fragCoord.x < 6.0) fragColor = vec4(vpos, 0.0, 1.0);
        else if(fragCoord.x < 7.0) fragColor = vec4(angle, 0.0, 0.0, 1.0);
        else if(fragCoord.x < 8.0) fragColor = vec4(vangle, 0.0, 0.0, 1.0);
        else fragColor = texelFetch(iChannel0, ivec2(fragCoord), 0);
    }
    else fragColor = texelFetch(iChannel0, ivec2(fragCoord), 0);
}

#define NUM_PRIMITIVES 5
#define PROXIMITY 0.015


const float DELTA = 0.001;

int seed = 539458;
int randInt() { seed = seed*0x343fd + 0x269ec3; return (seed>>16)&32767; }
float frand() { return float(randInt())/32767.0; }

void srand(ivec2 p, int frame) {
    int n = frame;
    n = (n<<13)^n; n = n*(n*n*15731+789221)+1376312589; 
    n += p.y;
    n = (n<<13)^n; n = n*(n*n*15731+789221)+1376312589;
    n += p.x;
    n = (n<<13)^n; n = n*(n*n*15731+789221)+1376312589;
    seed = n;
}

vec2 randomInCircle() {
    float an = 6.283185*frand();
    return vec2(cos(an),sin(an));
}

vec2 rotate2D(vec2 p, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return vec2(
        p.x * c - p.y * s,
        p.x * s + p.y * c
    );
}

float sdRoundedX( in vec2 p, in float w, in float r )
{
    p = abs(p);
    return length(p-min(p.x+p.y,w)*0.5) - r;
}

float sdRoundedBox(vec2 p, vec2 b, vec4 r) {
    r.xy = (p.x > 0.0) ? r.xy : r.zw;
    r.x = (p.y > 0.0) ? r.x : r.y;
    vec2 q = abs(p) - b + r.x;
    return min(max(q.x, q.y), 0.0) + length(max(q, 0.0)) - r.x;
}

float sdRoundedBox(vec2 pos, vec2 center, vec2 b, vec4 r, float angle) {
    vec2 p = pos - center;
    p = rotate2D(p, -angle);
    r.xy = (p.x > 0.0) ? r.xy : r.zw;
    r.x = (p.y > 0.0) ? r.x : r.y;
    vec2 q = abs(p) - b + r.x;
    return min(max(q.x, q.y), 0.0) + length(max(q, 0.0)) - r.x;
}

float sdOuter(vec2 p) {
    return sdRoundedX(p, 0.5, 0.075);
}

vec2 sdRoundedBoxGrad(vec2 p, vec2 c, vec2 b, vec4 r, float angle) {
    return vec2(
        sdRoundedBox(p + vec2(DELTA, 0.0), c, b, r, angle) - sdRoundedBox(p - vec2(DELTA, 0.0), c, b, r, angle),
        sdRoundedBox(p + vec2(0.0, DELTA), c, b, r, angle) - sdRoundedBox(p - vec2(0.0, DELTA), c, b, r, angle)
    ) / (2.0 * DELTA);
}

vec2 sdOuterGrad(vec2 p) {
    return vec2(
        sdOuter(p + vec2(DELTA, 0.0)) - sdOuter(p - vec2(DELTA, 0.0)),
        sdOuter(p + vec2(0.0, DELTA)) - sdOuter(p - vec2(0.0, DELTA))
    ) / (2.0 * DELTA);
}

void computeGrowthDerivatives(vec2 surfPos, vec2 pos, vec2 b, vec4 r, float angle, out vec2 db) {
    db = vec2(
        sdRoundedBox(surfPos, pos, b + vec2(DELTA, 0.0), r, angle) - 
        sdRoundedBox(surfPos, pos, b - vec2(DELTA, 0.0), r, angle),
        sdRoundedBox(surfPos, pos, b + vec2(0.0, DELTA), r, angle) - 
        sdRoundedBox(surfPos, pos, b - vec2(0.0, DELTA), r, angle)
    ) / (2.0 * DELTA);
}

void computePositionDerivatives(vec2 surfPos, vec2 pos, vec2 b, vec4 r, float angle, out vec2 dpos) {
    dpos = vec2(
        sdRoundedBox(surfPos, (pos + vec2(DELTA, 0.0)), b, r, angle) - 
        sdRoundedBox(surfPos, (pos - vec2(DELTA, 0.0)), b, r, angle),
        sdRoundedBox(surfPos, (pos + vec2(0.0, DELTA)), b, r, angle) - 
        sdRoundedBox(surfPos, (pos - vec2(0.0, DELTA)), b, r, angle)
    ) / (2.0 * DELTA);
}

void computeRadiusDerivatives(vec2 surfPos, vec2 pos, vec2 b, vec4 r, float angle, out vec4 dr) {
    dr = vec4(
        sdRoundedBox(surfPos, pos, b, r + vec4(DELTA,0,0,0), angle) - 
        sdRoundedBox(surfPos, pos, b, r - vec4(DELTA,0,0,0), angle),
        sdRoundedBox(surfPos, pos, b, r + vec4(0,DELTA,0,0), angle) - 
        sdRoundedBox(surfPos, pos, b, r - vec4(0,DELTA,0,0), angle),
        sdRoundedBox(surfPos, pos, b, r + vec4(0,0,DELTA,0), angle) - 
        sdRoundedBox(surfPos, pos, b, r - vec4(0,0,DELTA,0), angle),
        sdRoundedBox(surfPos, pos, b, r + vec4(0,0,0,DELTA), angle) - 
        sdRoundedBox(surfPos, pos, b, r - vec4(0,0,0,DELTA), angle)
    ) / (2.0 * DELTA);
}


#define PI 3.14159265359
void computeRotationUpdate(vec2 surfPos, vec2 pos, float angle, out float angleUpdate) {
    vec2 outerNormal = normalize(sdOuterGrad(surfPos));
    vec2 boxDir = rotate2D(vec2(1.0, 0.0), angle);

    float targetAngle1 = atan(outerNormal.y, outerNormal.x) + PI * 0.5;  // +90 degrees
    float targetAngle2 = atan(outerNormal.y, outerNormal.x) - PI * 0.5;  // -90 degrees

    float diff1 = targetAngle1 - angle;
    float diff2 = targetAngle2 - angle;

    diff1 = mod(diff1 + PI, 2.0 * PI) - PI;
    diff2 = mod(diff2 + PI, 2.0 * PI) - PI;

    angleUpdate = abs(diff1) < abs(diff2) ? diff1 : diff2;
}
